  1	package customerimporter;
  2	
  3	import java.io.BufferedReader;
  4	import java.io.IOException;
  5	import java.util.ArrayList;
  6	import java.util.Arrays;
  7	import java.util.List;
  8	import java.util.StringTokenizer;
  9	
 10	public class CustomerImporter {
 11	
 12	    private BufferedReader readStream;
 13	    private Customer newCustomer;
 14	    private String line;
 15	    private List<String> record;
 16	    private CustomerSystem system;
 17	
 18	    // instance creation
 19	
 20	    public static CustomerImporter from(BufferedReader aReadStream, CustomerSystem aCustomerSystem) {
 21	        return new CustomerImporter(aReadStream, aCustomerSystem);
 22	    }
 23	
 24	    // importing
 25	
 26	    public static void valueFrom(BufferedReader aReadStream, CustomerSystem aCustomerSystem) {
 27	        from(aReadStream, aCustomerSystem).value();
 28	    }
 29	
 30	    // error messages
 31	
 32	    public static String canNotImportAddressWithoutCustomerErrorDescription() {
 33	        return "Cannot import address without customer";
 34	    }
 35	
 36	    public static String invalidAddressRecordErrorDescription() {
 37	        return "Address record has to have six fields";
 38	    }
 39	
 40	    public static String invalidCustomerRecordErrorDescription() {
 41	        return "Invalid Customer record";
 42	    }
 43	
 44	    public static String invalidRecordTypeErrorDescription() {
 45	        return "Invalid record type";
 46	    }
 47	
 48	    // initialization
 49	
 50	    private CustomerImporter(BufferedReader aReadStream, CustomerSystem aCustomerSystem) {
 51	        readStream = aReadStream;
 52	        system = aCustomerSystem;
 53	    }
 54	
 55	    // evaluating
 56	
 57	    public void value() {
 58	        while (hasLineToImport()) {
 59	            createRecord();
 60	            importRecord();
 61	        }
 62	    }
 63	
 64	    // customer
 65	
 66	    public void assertValidCustomerRecord() {
 67	        if (record.size() != 5) throw new RuntimeException(invalidCustomerRecordErrorDescription());
 68	    }
 69	
 70	    public void importCustomer() {
 71	        String idType;
 72	        String idNumber;
 73	
 74	        assertValidCustomerRecord();
 75	
 76	        newCustomer = new Customer();
 77	        newCustomer.firstName(record.get(1));
 78	        newCustomer.lastName(record.get(2));
 79	        idType = record.get(3);
 80	        idNumber = record.get(4);
 81	
 82	        if (idType.equals("D")) {
 83	            int dniNumber;
 84	            if (!idNumber.chars().allMatch(idChar -> Character.isDigit(idChar))) throw new RuntimeException("Invalid DNI number");
 85	            dniNumber = Integer.parseInt(idNumber);
 86	            if (!(dniNumber >= 1 && dniNumber <= 99999999)) throw new RuntimeException("Invalid DNI number");
 87	        } else if (idType.equals("C")) {
 88	            // "23-25666777-9" size 13
 89	            if (!(idNumber.length() >= 12 && idNumber.length() <= 13)) throw new RuntimeException("Invalid CUIT number");
 90	            if (!(idNumber.charAt(2) == '-' && idNumber.charAt(idNumber.length() - 2) == '-')) throw new RuntimeException("Invalid CUIT number");
 91	            if (!Arrays.asList("20", "23", "24", "25", "26", "27", "30", "33", "34").contains(idNumber.substring(0, 2))) throw new RuntimeException("Invalid CUIT number");
 92	            if (!Character.isDigit(idNumber.charAt(idNumber.length() - 1))) throw new RuntimeException("Invalid CUIT number");
 93	            if (!idNumber.substring(3, idNumber.length() - 2).chars().allMatch(idChar -> Character.isDigit(idChar))) throw new RuntimeException("Invalid CUIT number");
 94	        } else {
 95	            throw new RuntimeException("Invalid identification type");
 96	        }
 97	
 98	        newCustomer.identificationType(idType);
 99	        newCustomer.identificationNumber(idNumber);
100	        system.add(newCustomer);
101	    }
102	
103	    public boolean isCustomerRecord() {
104	        return record.get(0).equals("C");
105	    }
106	
107	    // address
108	
109	    public void assertCustomerWasImported() {
110	        if (newCustomer == null) throw new RuntimeException(canNotImportAddressWithoutCustomerErrorDescription());
111	    }
112	
113	    public void assertValidAddressRecord() {
114	        if (record.size() != 6) throw new RuntimeException(invalidAddressRecordErrorDescription());
115	    }
116	
117	    public void importAddress() {
118	        Address newAddress;
119	        String zipCode;
120	        Object importedZipCode;
121	        String newZipcodeOldZipCode;
122	
123	        assertCustomerWasImported();
124	        assertValidAddressRecord();
125	
126	        newAddress = new Address();
127	        newAddress.streetName(record.get(1));
128	        newAddress.streetNumber(Integer.parseInt(record.get(2)));
129	        newAddress.town(record.get(3));
130	
131	        zipCode = record.get(4);
132	
133	        if (Character.isDigit(zipCode.charAt(0))) {
134	            if (!zipCode.chars().allMatch(aChar -> Character.isDigit(aChar))) throw new RuntimeException("Invalid old zipcode");
135	            importedZipCode = Integer.parseInt(zipCode);
136	            if (!((Integer) importedZipCode >= 1000 && (Integer) importedZipCode <= 9999)) throw new RuntimeException("Invalid old zipcode");
137	        } else if (Character.isLetter(zipCode.charAt(0))) {
138	            if (zipCode.length() != 8) throw new RuntimeException("Invalid new zipcode");
139	            newZipcodeOldZipCode = zipCode.substring(1, 5);
140	            if (!newZipcodeOldZipCode.chars().allMatch(aChar -> Character.isDigit(aChar))) throw new RuntimeException("Invalid new zipcode");
141	            if (!(Integer.parseInt(newZipcodeOldZipCode) > 999)) throw new RuntimeException("Invalid new zipcode");
142	            if (!zipCode.substring(zipCode.length() - 3).chars().allMatch(aChar -> Character.isLetter(aChar))) throw new RuntimeException("Invalid new zipcode");
143	            importedZipCode = zipCode;
144	        } else {
145	            throw new RuntimeException("Invalid identification type");
146	        }
147	
148	        newAddress.zipCode(importedZipCode);
149	        newAddress.province(record.get(5));
150	
151	        newCustomer.addAddress(newAddress);
152	    }
153	
154	    public boolean isAddressRecord() {
155	        return record.get(0).equals("A");
156	    }
157	
158	    // evaluating - private
159	
160	    private void assertRecordNotEmpty() {
161	        if (record.isEmpty()) throw new RuntimeException(invalidRecordTypeErrorDescription());
162	    }
163	
164	    private List<String> createRecord() {
165	        record = new ArrayList<>();
166	        StringTokenizer tokens = new StringTokenizer(line, ",");
167	        while (tokens.hasMoreTokens()) {
168	            record.add(tokens.nextToken());
169	        }
170	        return record;
171	    }
172	
173	    private boolean hasLineToImport() {
174	        try {
175	            line = readStream.readLine();
176	        } catch (IOException anIOException) {
177	            throw new RuntimeException(anIOException);
178	        }
179	        return line != null;
180	    }
181	
182	    private void importRecord() {
183	        assertRecordNotEmpty();
184	
185	        if (isCustomerRecord()) { importCustomer(); return; }
186	        if (isAddressRecord()) { importAddress(); return; }
187	
188	        throw new RuntimeException(invalidRecordTypeErrorDescription());
189	    }
190	}

