package customerimporter;

public abstract class CustomerSystem {

    // customers

    public abstract void add(Customer aCustomer);

    public abstract Customer customerWithIdentificationType(String anIdType, String anIdNumber);

    public abstract int numberOfCustomers();

    // transactions

    public abstract void beginTransaction();

    public abstract void commit();

    // system lifecycle

    public abstract void start();

    public abstract void stop();
}
package customerimporter;

import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;

public class TransientCustomerSystem extends CustomerSystem {

    private List<Customer> customers;

    // system lifecycle

    public void start() {
        customers = new ArrayList<>();
    }

    public void stop() {
        customers = null;
    }

    // transactions

    public void beginTransaction() {

    }

    public void commit() {

    }

    // customers

    public void add(Customer aCustomer) {
        customers.add(aCustomer);
    }

    public Customer customerWithIdentificationType(String anIdType, String anIdNumber) {
        for (Customer aCustomer : customers) {
            if (aCustomer.identificationType().equals(anIdType) && aCustomer.identificationNumber().equals(anIdNumber)) return aCustomer;
        }
        throw new NoSuchElementException("Object is not in the collection.");
    }

    public int numberOfCustomers() {
        return customers.size();
    }
}
package customerimporter;

import java.util.Arrays;

public class PersistentCustomerSystem extends CustomerSystem {

    private DataBaseSession session;

    // customers

    public void add(Customer aCustomer) {
        session.persist(aCustomer);
    }

    public Customer customerWithIdentificationType(String anIdType, String anIdNumber) {
        return session
            .select(aCustomer -> aCustomer.identificationType().equals(anIdType) && aCustomer.identificationNumber().equals(anIdNumber),
                    Customer.class)
            .iterator().next();
    }

    public int numberOfCustomers() {
        return session.selectAllOfType(Customer.class).size();
    }

    // transactions

    public void beginTransaction() {
        session.beginTransaction();
    }

    public void commit() {
        session.commit();
    }

    // system lifecycle

    public void start() {
        session = DataBaseSession.forConfiguration(Arrays.asList(Address.class, Customer.class));
    }

    public void stop() {
        session.close();
    }
}
package customerimporter;

import java.util.Arrays;
import java.util.NoSuchElementException;

public abstract class Environment {

    // current

    public static Environment current() {
        for (Environment anEnvironment : Arrays.asList(new DevelopmentEnvironment(), new IntegrationEnvironment())) {
            if (anEnvironment.isCurrent()) return anEnvironment;
        }
        throw new NoSuchElementException("Object is not in the collection.");
    }

    public abstract boolean isCurrent();

    // customer system

    public abstract CustomerSystem createCustomerSystem();
}
package customerimporter;

public class DevelopmentEnvironment extends Environment {

    // current

    public boolean isCurrent() {
        return true;
    }

    // customer system

    public CustomerSystem createCustomerSystem() {
        return new TransientCustomerSystem();
    }
}
package customerimporter;

public class IntegrationEnvironment extends Environment {

    // current

    public boolean isCurrent() {
        return !new DevelopmentEnvironment().isCurrent();
    }

    // customer system

    public CustomerSystem createCustomerSystem() {
        return new PersistentCustomerSystem();
    }
}

